def find_increasing_decreasing_sequences(a):
    n = len(a)
    if n == 1:
        return "YES\n0\n\n0\n"

    increasing = []
    decreasing = []
    i = 0

    while i < n - 1:
        if a[i] < a[i + 1]:
            start = i
            while i < n - 1 and a[i] < a[i + 1]:
                i += 1
            increasing.append(a[start:i + 1])
        elif a[i] > a[i + 1]:
            start = i
            while i < n - 1 and a[i] > a[i + 1]:
                i += 1
            decreasing.append(a[start:i + 1])
        else:
            return "NO"

    if i != n - 1:
        return "NO"

    for seq in increasing:
        if seq != sorted(seq):
            return "NO"

    for seq in decreasing:
        if seq != sorted(seq, reverse=True):
            return "NO"

    result = "YES\n"
    if increasing:
        result += str(len(increasing[-1])) + "\n" + " ".join(map(str, increasing[-1])) + "\n"
    else:
        result += "0\n\n"

    if decreasing:
        result += str(len(decreasing[-1])) + "\n" + " ".join(map(str, decreasing[-1])) + "\n"
    else:
        result += "0\n\n"

    return result

