from typing import List

def split_sequence(a: List[int]) -> str:
    n = len(a)
    if n == 1:
        return "YES\n0\n\n0\n"

    # Try to find the longest increasing subsequence ending at each position
    lis = [a[0]]
    prev = {a[0]: 0}
    for i in range(1, n):
        if a[i] > lis[-1]:
            lis.append(a[i])
            prev[a[i]] = i
        else:
            idx = bisect.bisect_left(lis, a[i])
            lis[idx] = a[i]
            prev[a[i]] = idx

    # Try to find the longest decreasing subsequence starting at each position
    lds = [a[n-1]]
    next_ = {a[n-1]: n-1}
    for i in range(n-2, -1, -1):
        if a[i] < lds[-1]:
            lds.append(a[i])
            next_[a[i]] = i
        else:
            idx = bisect.bisect_right(lds, a[i], key=lambda x: -x)
            lds[idx] = a[i]
            next_[a[i]] = idx

    # Check all possible points to split the sequence
    for i in range(n-1):
        if a[i] <= a[i+1]:
            continue
        increasing = a[:i+1]
        decreasing = a[i+1:]
        if increasing == sorted(increasing) and decreasing == sorted(decreasing, reverse=True):
            return f"YES\n{len(increasing)}\n{' '.join(map(str, increasing))}\n{len(decreasing)}\n{' '.join(map(str, decreasing))}"

    return "NO"

