def split_sequence(a):
    n = len(a)
    if n == 0:
        return "YES", [], []

    increasing = [a[0]]
    decreasing = [a[-1]]

    i, j = 1, n - 2

    while i <= j:
        if a[i] > increasing[-1]:
            increasing.append(a[i])
            i += 1
        elif a[j] < decreasing[-1]:
            decreasing.append(a[j])
            j -= 1
        else:
            break

    if i > j:
        return "YES", increasing, list(reversed(decreasing))

    return "NO", [], []

